"""
    Find the value of an integer at a specific digit when represented in a
    particular base.

    Args:
        decimal(int): A number represented in base 10 (positive integer).
        digit(int): The digit to find where zero is the first, lowest, digit.
        base(int): The base to use (default 10).

    Returns:
        The value at specified digit in the input decimal.
        This output value is represented as a base 10 integer.

    Examples:
        >>> digit(201, 0)
        1
        >>> digit(201, 1)
        0
        >>> digit(201, 2)
        2
        >>> tuple(digit(253, i, 2) for i in range(8))
        (1, 0, 1, 1, 1, 1, 1, 1)

        # Find the lowest digit of a large hexidecimal number
        >>> digit(123456789123456789, 0, 16)
        5
    """
def digit(decimal: Any, digit: Any, input_base: Any = 10) -> object {
    if (decimal == 0) {
        return 0;
    }
    if (digit != 0) {
        return ((decimal // (input_base ** digit)) % input_base);
    } else {
        return (decimal % input_base);
    }
}

"""
    Examples
    --------
    {
        "head":["PC","Mac","Windows","Ubuntu"],
        "body":[
            ["X1","x","o","o"],
            ["Surface","x","o","o"],
            ["MacBook Air","o","o","o"]
        ]
    }
    """
def dict_to_table(_dict: Any) -> object {
    dict_table = "";
    head = _dict["head"];
    dict_table += "|" + "|".join([str(n) for n in head]) + "|\n";
    dict_table += "|" + "".join(["-|" for i in range(len(head))]) + "\n";
    body = _dict["body"];
    for row in body {
        dict_table += "|" + "|".join([str(n) for n in row]) + "|\n";
    }
    return dict_table;
}

"""Function to count words from title occuring inside the article body"""
def count(article: Any) -> object {
    numberOfWords = 0;
    heading = article[0].split();
    for word in heading {
        if (word in article[1]) {
            numberOfWords += 1;
        }
    }
    return (numberOfWords / len(heading));
}

